import { useQuery, useQueryClient } from "@tanstack/react-query";
import { queryCoins } from "../api";
import { Link } from "react-router-dom";
import { themeState } from "../atoms";
import { useAtom } from "jotai";
import { themeMap, themeMode } from "../styles";

function Coins() {
  const queryClient = useQueryClient();
  const { data, isPending } = useQuery(queryCoins);
  const [themeMode, setThemeMode] = useAtom(themeState);

  const handleTheme = (event: React.ChangeEvent<HTMLSelectElement>) => {
    console.log(event.currentTarget.value);
    setThemeMode(event.currentTarget.value as themeMode);
  };

  console.log("Rendered");
  return (
    <>
      <h1>Coins: {isPending ? "Loading..." : "Loaded"}</h1>
      <button
        onClick={() => {
          queryClient.invalidateQueries();
        }}
      >
        Refetch Coins
      </button>

      <select value={themeMode} onChange={handleTheme}>
        {Object.keys(themeMap).map((option, index) => (
          <option key={index}>{option}</option>
        ))}
      </select>

      <ul>
        {data?.map((coinData, index) => (
          <li key={coinData.id}>
            <Link
              to={`/${coinData.id}`}
              state={{ coinName: coinData.name, coinId: coinData.id }}
            >
              {coinData.name} ({coinData.id})
            </Link>
          </li>
        ))}
      </ul>
    </>
  );
}
export default Coins;
