import { useParams, Outlet, useLocation, useNavigate } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { queryCoin } from "../api";
import { Link } from "react-router-dom";
import { themeMode, themeMap } from "../styles";
import { themeState } from "../atoms";
import { useAtom } from "jotai";

function Coin({ coinId: propCoinId }: TCoinProps) {
  const navigate = useNavigate();
  const { state } = useLocation() as ILocationState;
  const { coinId: locationCoinId, coinName } = state || {};
  const { coinId: paramCoinId } = useParams<{ coinId: string }>();
  const coinId = propCoinId || paramCoinId || locationCoinId;
  const [themeMode, setThemeMode] = useAtom(themeState);
  const { data, isPending, isError, isFetching } = useQuery(queryCoin(coinId));

  const handleTheme = (event: React.ChangeEvent<HTMLSelectElement>) => {
    setThemeMode(event.currentTarget.value as themeMode);
  };

  return (
    <>
      <h1>
        Coin: {coinName || coinId}{" "}
        {!isError ? (isPending ? "loading" : "loaded") : "Not Found!"}
      </h1>
      <Link to="/">
        <button>Back to Coins</button>
      </Link>
      <select value={themeMode} onChange={handleTheme}>
        {Object.keys(themeMap).map((option, index) => (
          <option key={index}>{option}</option>
        ))}
      </select>
      <p>{data?.description}</p>
      {!isError && !isFetching && (
        <>
          <button onClick={() => navigate("chart")}>Chart</button>
          <button onClick={() => navigate("price")}>Price</button>
          <button onClick={() => navigate(".")}>Close</button>
          <Outlet
            context={{
              coinId: data?.id || coinId,
              coinName: data?.name || coinName,
            }}
          />
        </>
      )}
    </>
  );
}

export default Coin;
